   182→        "background:" + cfg.errorColor + " !important;color:#fff !important;border:none !important;" +
   183→        "border-radius:" + rad + " !important;padding:8px 16px !important;font-size:13px !important;" +
   184→        "cursor:pointer !important;width:100% !important;font-weight:600 !important" +
