   435→
   436→    injectCss(WID, cfg, rad);
   437→
   438→    // Additional styles for floating UI
   439→    var floatCss =
   440→      "#" + WID + "-float{position:fixed !important;bottom:20px !important;right:20px !important;z-index:9998 !important;display:flex !important;flex-direction:column !important;align-items:flex-end !important;gap:10px !important}" +
   441→      "#" + WID + "-panel{" +
   442→        "background:" + cfg.backgroundColor + " !important;border-radius:" + rad + " !important;" +
   443→        "box-shadow:0 8px 32px rgba(0,0,0,.18) !important;overflow:hidden !important;" +
   444→        "transition:opacity .2s,transform .2s;transform-origin:bottom right" +
   445→      "}" +
   446→      "#" + WID + "-panel.zcc-hidden{display:none !important}" +
   447→      "#" + WID + "-panel .zcc-panel-header{" +
   448→        "display:flex !important;align-items:center !important;justify-content:space-between !important;" +
   449→        "padding:14px 16px 0 !important;margin-bottom:0 !important" +
   450→      "}" +
   451→      "#" + WID + "-panel .zcc-panel-close{" +
   452→        "background:none !important;border:none !important;cursor:pointer !important;font-size:20px !important;line-height:1 !important;" +
