   454→      "}" +
   455→      "#" + WID + "-panel .zcc-panel-close:hover{opacity:1 !important}" +
   456→      "#" + WID + "-trigger{" +
   457→        "background:" + cfg.primaryColor + " !important;color:#fff !important;border:none !important;" +
   458→        "border-radius:50px !important;padding:12px 20px !important;font-size:14px !important;font-weight:600 !important;" +
   459→        "cursor:pointer !important;box-shadow:0 4px 12px rgba(0,0,0,.2) !important;white-space:nowrap !important" +
   460→      "}" +
   461→      "#" + WID + "-trigger:hover{opacity:.9 !important}";
   462→
   463→    var floatStyle = document.createElement("style");
   464→    floatStyle.textContent = floatCss;
