   467→    // Build floating shell
   468→    var floatEl = document.createElement("div");
   469→    floatEl.id = WID + "-float";
   470→    floatEl.innerHTML =
   471→      '<div id="' + WID + '-panel" class="zcc-hidden">' +
   472→        '<div class="zcc-panel-header">' +
   473→          '<span style="font-size:13px;font-weight:600;color:' + cfg.textColor + '">Delivery Check</span>' +
   474→          '<button class="zcc-panel-close" id="' + WID + '-close" type="button" aria-label="Close">&times;</button>' +
