// Fetch the active (MAIN) theme so we can build a precise deep-link
// into the Theme Editor's App Embeds panel.
let activeThemeName: string | null = null;
let themeEditorUrl = `https://${shop}/admin/themes/current/editor`;
let themeEditorAppEmbedsUrl = `https://${shop}/admin/themes/current/editor?context=apps`;

try {
  const themesResponse = await admin.graphql(`
    query GetActiveTheme {
      themes(first: 5, roles: [MAIN]) {
        nodes {
          id
          name
          role
        }
      }
    }
  `);
  const themesData = (await themesResponse.json()) as {
    data: {
      themes: {
        nodes: { id: string; name: string; role: string }[];
      };
    };
  };
  const mainTheme = themesData.data?.themes?.nodes?.[0];
  if (mainTheme) {
    // Extract numeric ID from GID like "gid://shopify/OnlineStoreTheme/123456"
    const numericId = mainTheme.id.split("/").pop();
    activeThemeName = mainTheme.name;
    themeEditorUrl = `https://${shop}/admin/themes/${numericId}/editor`;
    // ?context=apps opens the App Embeds tab directly
    themeEditorAppEmbedsUrl = `https://${shop}/admin/themes/${numericId}/editor?context=apps`;
  }
} catch {
  // Non-fatal — fall back to generic theme editor URL
}

return { config, themeEditorUrl, themeEditorAppEmbedsUrl, activeThemeName };

input.new_string:
// Fetch the active (MAIN) theme and detect whether our App Embed block
// is actually enabled in it by reading config/settings_data.json.
let activeThemeName: string | null = null;
let themeEditorUrl = `https://${shop}/admin/themes/current/editor`;
let themeEditorAppEmbedsUrl = `https://${shop}/admin/themes/current/editor?context=apps`;
let appEmbedEnabled = false;

try {
  // Step 1 — get the published theme GID
  const themesResponse = await admin.graphql(`
    query GetActiveTheme {
      themes(first: 5, roles: [MAIN]) {
        nodes {
          id
          name
        }
      }
    }
  `);
  const themesData = (await themesResponse.json()) as {
    data: { themes: { nodes: { id: string; name: string }[] } };
  };
  const mainTheme = themesData.data?.themes?.nodes?.[0];

  if (mainTheme) {
    const numericId = mainTheme.id.split("/").pop();
    activeThemeName = mainTheme.name;
    themeEditorUrl = `https://${shop}/admin/themes/${numericId}/editor`;
    themeEditorAppEmbedsUrl = `https://${shop}/admin/themes/${numericId}/editor?context=apps`;

    // Step 2 — read settings_data.json to check if our app embed block
    // is present and not disabled.
    // Shopify stores app embed blocks under current.blocks[uuid].type
    // The type value contains our extension handle "zip-code-checker".
    try {
      const filesResponse = await admin.graphql(
        `query GetThemeSettings($themeId: ID!) {
          theme(id: $themeId) {
            files(filenames: ["config/settings_data.json"]) {
              nodes {
                body {
                  ... on OnlineStoreThemeFileBodyText {
                    content
                  }
                }
              }
            }
          }
        }`,
        { variables: { themeId: mainTheme.id } },
      );
      const filesData = (await filesResponse.json()) as {
        data: {
          theme: {
            files: {
              nodes: {
                body: { content?: string } | null;
              }[];
            };
          };
        };
      };
      const rawContent =
        filesData.data?.theme?.files?.nodes?.[0]?.body as
        | { content?: string }
        | null
        | undefined;
      const content = rawContent?.content;

      if (content) {
        const settingsData = JSON.parse(content) as {
          current?: { blocks?: Record<string, unknown> };
        };
        const blocks = settingsData?.current?.blocks ?? {};
        // A block is "ours" when its type contains our extension handle
        // ("zip-code-checker") and the block handle ("app-embed").
        // It is active when disabled !== true.
        appEmbedEnabled = Object.values(blocks).some((block) => {
          const b = block as { type?: string; disabled?: boolean };
          return (
            typeof b.type === "string" &&
            b.type.includes("zip-code-checker") &&
            b.type.includes("app-embed") &&
            b.disabled !== true
          );
        });
      }
    } catch {
      // settings_data.json query failed — appEmbedEnabled stays false
    }
  }
} catch {
  // Themes query failed — fall back to generic URLs
}

return {
  config,
  themeEditorUrl,
  themeEditorAppEmbedsUrl,
  activeThemeName,
  appEmbedEnabled,
};

