          )}
          {previewState === "success" && cfg.showReturnPolicy && (
            <div className="zcc-return-policy">30-day returns accepted. Exchange within 7 days.</div>
          )}
          {(previewState === "error" || previewState === "notfound") &&
            cfg.showWaitlistOnFailure && (
