                          >
                            <Text as="p" variant="bodySm" alignment="center" tone="text-inverse" fontWeight="bold">
                              1
                            </Text>
                          </Box>
                          <BlockStack gap="100">
                            <Text as="p" variant="bodyMd" fontWeight="semibold">
                              Enable the App Embed (master on/off switch)
                            </Text>
                            <Text as="p" variant="bodySm" tone="subdued">
                              In Theme Editor → <strong>App Embeds</strong>, find{" "}
                              <strong>Zip Code Checker</strong> and toggle it{" "}
                              <strong>on</strong>.
                            </Text>
                            <Box paddingBlockStart="100">
                              <Button
                                variant="primary"
                                url={themeEditorAppEmbedsUrl}
                                target="_blank"
                                icon={ExternalIcon}
                              >
                                Open App Embeds
                              </Button>
                            </Box>
                          </BlockStack>
                        </InlineStack>
                      </Box>

                      {/* Step 2 */}
                      <Box
                        padding="400"
                        background="bg-surface-secondary"
                        borderRadius="200"
                      >
                        <InlineStack gap="300" blockAlign="start">
                          <Box
                            minWidth="24px"
                            minHeight="24px"
                            background="bg-surface-tertiary"
                            borderRadius="full"
                          >
                            <Text as="p" variant="bodySm" alignment="center" fontWeight="bold">
                              2
                            </Text>
                          </Box>
                          <BlockStack gap="100">
                            <Text as="p" variant="bodyMd" fontWeight="semibold">
                              Add the Widget Block to your product pages
                            </Text>
                            <Text as="p" variant="bodySm" tone="subdued">
                              Go to a <strong>Product</strong> template →{" "}
                              <strong>Add block</strong> → select{" "}
                              <strong>Zip Code Checker</strong> under Apps →{" "}
                              <strong>Save</strong>.
                            </Text>
                            <Box paddingBlockStart="100">
                              <Button
                                url={`${themeEditorUrl}?template=product`}
                                target="_blank"
                                icon={ExternalIcon}
                              >
                                Open Product Template
                              </Button>
                            </Box>
                          </BlockStack>
                        </InlineStack>
                      </Box>
                    </BlockStack>

                    <Text as="p" variant="bodySm" tone="subdued">
                      After enabling the app embed and saving in Theme Editor,
                      click <strong>Refresh Status</strong> above — the badge
                      will turn green when the app is live.
                    </Text>
                  </BlockStack>
                )}
              </BlockStack>
            </Card>
          </Layout.Section>

          {/* Settings + Preview */}
          <Layout.Section>
            <InlineGrid columns={{ xs: 1, md: 2 }} gap="400" alignItems="start">
              {/* ── Settings Column ── */}
              <BlockStack gap="400">
                {/* Layout */}
                <Card>
                  <BlockStack gap="400">
                    <Text as="h2" variant="headingMd">
                      Layout
                    </Text>
                    <Select
                      label="Widget Position"
                      options={positionOptions}
                      value={position}
                      onChange={handlePositionChange}
                      helpText={
                        position === "floating"
                          ? "Widget appears as a fixed button in the bottom-right corner of every page."
                          : position === "popup"
                          ? "A trigger button shows in the block. Clicking it opens a centered popup overlay."
                          : "Widget renders directly where you place the block in the Theme Editor."
                      }
                    />
                    <TextField
                      label="Border Radius (px)"
                      type="number"
                      value={borderRadius}
                      onChange={handleBorderRadiusChange}
                      autoComplete="off"
                      helpText="Roundness of corners. 0 = square, 16 = very rounded."
                    />
                  </BlockStack>
                </Card>

                {/* Colors */}
                <Card>
                  <BlockStack gap="400">
                    <Text as="h2" variant="headingMd">
                      Colors
                    </Text>
                    <InlineStack gap="300" wrap>
                      <div style={{ flex: 1, minWidth: "140px" }}>
