import { useState, useCallback, useEffect } from "react";
import type {
  ActionFunctionArgs,
  HeadersFunction,
  LoaderFunctionArgs,
} from "react-router";
import { useFetcher, useLoaderData, useNavigate, useRevalidator } from "react-router";
import { useAppBridge } from "@shopify/app-bridge-react";
import { authenticate } from "../shopify.server";
import { boundary } from "@shopify/shopify-app-react-router/server";
import db from "../db.server";
import {
  Page,
  Layout,
  Card,
  BlockStack,
  InlineStack,
  InlineGrid,
  Text,
  Button,
  TextField,
  Select,
  Checkbox,
  Divider,
  Box,
  Banner,
  Badge,
} from "@shopify/polaris";
import { ExternalIcon } from "@shopify/polaris-icons";

export const loader = async ({ request }: LoaderFunctionArgs) => {
  const { session, admin } = await authenticate.admin(request);
  const shop = session.shop;

  let config = await db.widgetConfig.findUnique({ where: { shop } });

  if (!config) {
    config = await db.widgetConfig.create({ data: { shop } });
  }

  // Fetch the active (MAIN) theme and detect whether our App Embed block
  // is actually enabled in it by reading config/settings_data.json.
  let activeThemeName: string | null = null;
  let themeEditorUrl = `https://${shop}/admin/themes/current/editor`;
  let themeEditorAppEmbedsUrl = `https://${shop}/admin/themes/current/editor?context=apps`;
  let appEmbedEnabled = false;

  try {
    // Step 1 — get the published theme GID
    const themesResponse = await admin.graphql(`
      query GetActiveTheme {
        themes(first: 5, roles: [MAIN]) {
          nodes {
            id
            name
          }
        }
      }
    `);
    const themesData = (await themesResponse.json()) as {
      data: { themes: { nodes: { id: string; name: string }[] } };
    };
    const mainTheme = themesData.data?.themes?.nodes?.[0];

    if (mainTheme) {
      const numericId = mainTheme.id.split("/").pop();
      activeThemeName = mainTheme.name;
      themeEditorUrl = `https://${shop}/admin/themes/${numericId}/editor`;
      themeEditorAppEmbedsUrl = `https://${shop}/admin/themes/${numericId}/editor?context=apps`;

      // Step 2 — read settings_data.json via REST API to check app embed state.
      const embedDebug: {
        httpStatus: number | null;
        hasContent: boolean;
        blockTypes: string[];
        error: string | null;
        rawBlocksSnippet: string | null;
      } = {
        httpStatus: null,
        hasContent: false,
        blockTypes: [],
        error: null,
        rawBlocksSnippet: null,
      };

      try {
        // URLSearchParams encodes brackets → use manual string to ensure
        // Shopify's REST API receives "asset[key]" literally.
        const assetUrl = `https://${shop}/admin/api/2026-01/themes/${numericId}/assets.json?asset%5Bkey%5D=config%2Fsettings_data.json`;
        const assetRes = await fetch(assetUrl, {
          headers: {
            "X-Shopify-Access-Token": session.accessToken ?? "",
          },
        });

        embedDebug.httpStatus = assetRes.status;

        if (assetRes.ok) {
          const assetJson = (await assetRes.json()) as {
            asset?: { value?: string };
          };
          const content = assetJson?.asset?.value;
          embedDebug.hasContent = !!content;

          if (content) {
            const settingsData = JSON.parse(content) as {
              current?: { blocks?: Record<string, unknown> };
            };
            const blocks = settingsData?.current?.blocks ?? {};
            embedDebug.rawBlocksSnippet = JSON.stringify(blocks).slice(0, 800);

            // Collect all block types for debug display
            embedDebug.blockTypes = Object.values(blocks)
              .map((b) => (b as { type?: string }).type ?? "")
              .filter(Boolean);

            // Match any block whose type contains "app-embed" (covers both
            // hyphen and underscore variants) and is not disabled.
            appEmbedEnabled = Object.values(blocks).some((block) => {
              const b = block as { type?: string; disabled?: boolean };
              return (
                typeof b.type === "string" &&
                (b.type.includes("app-embed") || b.type.includes("app_embed")) &&
                b.disabled !== true
              );
            });
          }
        } else {
          const errText = await assetRes.text().catch(() => "");
          embedDebug.error = `HTTP ${assetRes.status}: ${errText.slice(0, 200)}`;
        }
      } catch (e) {
        embedDebug.error = String(e);
      }
    }
  } catch {
    // Themes query failed — fall back to generic URLs
  }

  return {
    config,
    themeEditorUrl,
    themeEditorAppEmbedsUrl,
    activeThemeName,
    appEmbedEnabled,
    embedDebug,
  };
};

// Helper: sync widget config to an App Installation metafield so the
// storefront Liquid block can read it via app.metafields.zip_checker.widget_config.value
//
// IMPORTANT: ownerId MUST be the App Installation GID (not the Shop GID).
// app.metafields in Liquid only surfaces metafields owned by the App Installation.
// Using the Shop GID writes to shop metafields which are invisible to app.metafields.
async function syncConfigMetafield(
  admin: Awaited<ReturnType<typeof authenticate.admin>>["admin"],
  configData: Record<string, unknown>,
) {
  try {
    // Step 1: get the App Installation GID
    const installResponse = await admin.graphql(
      `query { currentAppInstallation { id } }`,
    );
    const installJson = (await installResponse.json()) as {
      data: { currentAppInstallation: { id: string } };
    };
    const appInstallationGid = installJson.data.currentAppInstallation.id;

    // Step 2: write the metafield to the App Installation
    // Namespace must be plain "zip_checker" (no "$app:" prefix) for App Installation metafields.
    // The Liquid block reads: app.metafields.zip_checker.widget_config.value
    const metaResponse = await admin.graphql(
      `mutation MetafieldsSet($metafields: [MetafieldsSetInput!]!) {
        metafieldsSet(metafields: $metafields) {
          metafields { id namespace key }
          userErrors { field message }
        }
      }`,
      {
        variables: {
          metafields: [
            {
              ownerId: appInstallationGid,
              namespace: "zip_checker",
              key: "widget_config",
              type: "json",
              value: JSON.stringify(configData),
            },
          ],
        },
      },
    );
    const metaJson = (await metaResponse.json()) as {
      data: {
        metafieldsSet: {
          metafields: { id: string; namespace: string; key: string }[];
          userErrors: { field: string; message: string }[];
        };
      };
    };

    if (metaJson.data.metafieldsSet.userErrors.length > 0) {
      console.error(
        "metafieldsSet userErrors:",
        metaJson.data.metafieldsSet.userErrors,
      );
    }
  } catch (e) {
    // Non-fatal — the API fallback still works
    console.error("Failed to sync widget config metafield:", e);
  }
}

