    31→    31→export const loader = async ({ request }: LoaderFunctionArgs) => {
    32→    32→  const { session, admin } = await authenticate.admin(request);
    33→    33→  const shop = session.shop;
    34→    34→
    35→    35→  let config = await db.widgetConfig.findUnique({ where: { shop } });
    36→    36→
    37→    37→  if (!config) {
    38→    38→    config = await db.widgetConfig.create({ data: { shop } });
    39→    39→  }
    40→    40→
    41→    41→  // Fetch the active (MAIN) theme and detect whether our App Embed block
    42→    42→  // is actually enabled in it by reading config/settings_data.json.
    43→    43→  let activeThemeName: string | null = null;
    44→    44→  let themeEditorUrl = `https://${shop}/admin/themes/current/editor`;
    45→    45→  let themeEditorAppEmbedsUrl = `https://${shop}/admin/themes/current/editor?context=apps`;
    46→    46→  let appEmbedEnabled = false;
    47→    47→  let embedDebug: {
    48→    48→    httpStatus: number | null;
    49→    49→    hasContent: boolean;
    50→    50→    blockTypes: string[];
    51→    51→    error: string | null;
    52→    52→    rawBlocksSnippet: string | null;
    53→    53→  } = {
    54→    54→    httpStatus: null,
    55→    55→    hasContent: false,
    56→    56→    blockTypes: [],
    57→    57→    error: null,
    58→    58→    rawBlocksSnippet: null,
    59→    59→  };
    60→    60→
    61→    61→  try {
    62→    62→    // Step 1 — get the published theme via REST API.
    63→    63→    // GraphQL `themes(roles:[MAIN])` is unreliable in 2026-01 and returns
    64→    64→    // empty nodes. REST /themes.json?role=main is the canonical approach.
    65→    65→    const themesRes = await fetch(
    66→    66→      `https://${shop}/admin/api/2026-01/themes.json?role=main`,
    67→    67→      { headers: { "X-Shopify-Access-Token": session.accessToken ?? "" } },
    68→    68→    );
    69→    69→
    70→    70→    if (themesRes.ok) {
    71→    71→      const themesJson = (await themesRes.json()) as {
    72→    72→        themes?: { id: number; name: string }[];
    73→    73→      };
    74→    74→      const mainTheme = themesJson.themes?.[0];
    75→    75→
    76→    76→      if (mainTheme) {
    77→    77→        const numericId = String(mainTheme.id);
    78→    78→        activeThemeName = mainTheme.name;
    79→    79→        themeEditorUrl = `https://${shop}/admin/themes/${numericId}/editor`;
    80→    80→        themeEditorAppEmbedsUrl = `https://${shop}/admin/themes/${numericId}/editor?context=apps`;
    81→    81→
    82→    82→        // Step 2 — read settings_data.json to detect app embed state.
    83→    83→        // Shopify stores app embed blocks in config/settings_data.json under:
    84→    84→        //   current.blocks[uuid] = { type: "shopify://apps/{handle}/blocks/app-embed", disabled: false }
    85→    85→        try {
    86→    86→          const assetUrl = `https://${shop}/admin/api/2026-01/themes/${numericId}/assets.json?asset%5Bkey%5D=config%2Fsettings_data.json`;
    87→    87→          const assetRes = await fetch(assetUrl, {
    88→    88→            headers: { "X-Shopify-Access-Token": session.accessToken ?? "" },
    89→    89→          });
    90→    90→
    91→    91→          embedDebug.httpStatus = assetRes.status;
    92→    92→
    93→    93→          if (assetRes.ok) {
    94→    94→            const assetJson = (await assetRes.json()) as {
    95→    95→              asset?: { value?: string };
    96→    96→            };
    97→    97→            const content = assetJson?.asset?.value;
    98→    98→            embedDebug.hasContent = !!content;
    99→    99→
   100→   100→            if (content) {
   101→   101→              const settingsData = JSON.parse(content) as {
   102→   102→                current?: { blocks?: Record<string, unknown> };
   103→   103→              };
   104→   104→              const blocks = settingsData?.current?.blocks ?? {};
   105→   105→              embedDebug.rawBlocksSnippet = JSON.stringify(blocks).slice(0, 800);
   106→   106→
   107→   107→              embedDebug.blockTypes = Object.values(blocks)
   108→   108→                .map((b) => (b as { type?: string }).type ?? "")
   109→   109→                .filter(Boolean);
   110→   110→
   111→   111→              // Match on "app-embed" OR "app_embed" — covers file-name variants
   112→   112→              appEmbedEnabled = Object.values(blocks).some((block) => {
   113→   113→                const b = block as { type?: string; disabled?: boolean };
   114→   114→                return (
   115→   115→                  typeof b.type === "string" &&
   116→   116→                  (b.type.includes("app-embed") || b.type.includes("app_embed")) &&
   117→   117→                  b.disabled !== true
   118→   118→                );
   119→   119→              });
   120→   120→            }
   121→   121→          } else {
   122→   122→            const errText = await assetRes.text().catch(() => "");
   123→   123→            embedDebug.error = `HTTP ${assetRes.status}: ${errText.slice(0, 200)}`;
   124→   124→          }
   125→   125→        } catch (e) {
   126→   126→          embedDebug.error = String(e);
   127→   127→        }
   128→   128→      } else {
   129→   129→        embedDebug.error = "No main theme found in REST response";
   130→   130→      }
   131→   131→    } else {
   132→   132→      embedDebug.error = `Themes REST HTTP ${themesRes.status}`;
   133→   133→    }
   134→   134→  } catch (e) {
   135→   135→    embedDebug.error = `Outer catch: ${String(e)}`;
   136→   136→  }
   137→   137→
   138→   138→  return {
   139→   139→    config,
   140→   140→    themeEditorUrl,
   141→   141→    themeEditorAppEmbedsUrl,
   142→   142→    activeThemeName,
   143→   143→    appEmbedEnabled,
   144→   144→    embedDebug,
   145→   145→  };
   146→   146→};
