                              autoComplete="off"
                            />
                          </InlineStack>
                        </BlockStack>
                      </div>
                      <div style={{ flex: 1, minWidth: "140px" }}>
                        <BlockStack gap="100">
                          <Text as="p" variant="bodySm">
                            Success Color
                          </Text>
                          <InlineStack gap="200" blockAlign="center">
                            <input
                              type="color"
                              value={successColor}
                              onChange={(e) => handleSuccessColorChange(e.target.value)}
                              style={{
                                width: "36px",
                                height: "36px",
                                border: "1px solid #ccc",
                                borderRadius: "6px",
                                cursor: "pointer",
                                padding: "2px",
                              }}
                            />
                            <TextField
                              label="Success"
                              labelHidden
                              value={successColor}
                              onChange={handleSuccessColorChange}
                              autoComplete="off"
                            />
                          </InlineStack>
                        </BlockStack>
                      </div>
                    </InlineStack>
                    <InlineStack gap="300" wrap>
                      <div style={{ flex: 1, minWidth: "140px" }}>
                        <BlockStack gap="100">
                          <Text as="p" variant="bodySm">
