                                padding: "2px",
                              }}
                            />
                            <TextField
                              label="Error"
                              labelHidden
                              value={errorColor}
                              onChange={handleErrorColorChange}
                              autoComplete="off"
                            />
                          </InlineStack>
                        </BlockStack>
                      </div>
                      <div style={{ flex: 1, minWidth: "140px" }}>
                        <BlockStack gap="100">
                          <Text as="p" variant="bodySm">
                            Background
                          </Text>
                          <InlineStack gap="200" blockAlign="center">
                            <input
                              type="color"
                              value={backgroundColor}
                              onChange={(e) => handleBackgroundColorChange(e.target.value)}
                              style={{
                                width: "36px",
                                height: "36px",
                                border: "1px solid #ccc",
                                borderRadius: "6px",
                                cursor: "pointer",
                                padding: "2px",
                              }}
                            />
                            <TextField
                              label="BG"
                              labelHidden
                              value={backgroundColor}
                              onChange={handleBackgroundColorChange}
                              autoComplete="off"
                            />
                          </InlineStack>
                        </BlockStack>
                      </div>
                    </InlineStack>
                    <BlockStack gap="100">
                      <Text as="p" variant="bodySm">
                        Text Color
                      </Text>
                      <InlineStack gap="200" blockAlign="center">
                        <input
                          type="color"
                          value={textColor}
                          onChange={(e) => handleTextColorChange(e.target.value)}
                          style={{
                            width: "36px",
                            height: "36px",
                            border: "1px solid #ccc",
                            borderRadius: "6px",
                            cursor: "pointer",
                            padding: "2px",
                          }}
                        />
                        <TextField
                          label="Text"
                          labelHidden
                          value={textColor}
