        activeThemeName = mainTheme.name;
        themeEditorUrl = `https://${shop}/admin/themes/${numericId}/editor`;
        themeEditorAppEmbedsUrl = `https://${shop}/admin/themes/${numericId}/editor?context=apps`;

        // Step 2 — read settings_data.json to detect app embed state.
        // Shopify stores app embed blocks in config/settings_data.json under:
        //   current.blocks[uuid] = { type: "shopify://apps/{handle}/blocks/app-embed", disabled: false }
        try {
          const assetUrl = `https://${shop}/admin/api/2026-01/themes/${numericId}/assets.json?asset%5Bkey%5D=config%2Fsettings_data.json`;
          const assetRes = await fetch(assetUrl, {
            headers: { "X-Shopify-Access-Token": session.accessToken ?? "" },
          });

          embedDebug.httpStatus = assetRes.status;

          if (assetRes.ok) {
            const assetJson = (await assetRes.json()) as {
              asset?: { value?: string };
            };
            const content = assetJson?.asset?.value;
            embedDebug.hasContent = !!content;

            if (content) {
              const settingsData = JSON.parse(content) as {
                current?: { blocks?: Record<string, unknown> };
              };
              const blocks = settingsData?.current?.blocks ?? {};
              embedDebug.rawBlocksSnippet = JSON.stringify(blocks).slice(0, 800);

              embedDebug.blockTypes = Object.values(blocks)
                .map((b) => (b as { type?: string }).type ?? "")
                .filter(Boolean);

              // Match on "app-embed" OR "app_embed" — covers file-name variants
              appEmbedEnabled = Object.values(blocks).some((block) => {
                const b = block as { type?: string; disabled?: boolean };
                return (
                  typeof b.type === "string" &&
                  (b.type.includes("app-embed") || b.type.includes("app_embed")) &&
                  b.disabled !== true
                );
              });
            }
          } else {
            const errText = await assetRes.text().catch(() => "");
            embedDebug.error = `HTTP ${assetRes.status}: ${errText.slice(0, 200)}`;
          }
        } catch (e) {
          embedDebug.error = String(e);
        }
      } else {
        embedDebug.error = "No main theme found in REST response";
      }
    } else {
      embedDebug.error = `Themes REST HTTP ${themesRes.status}`;
    }
  } catch (e) {
    embedDebug.error = `Outer catch: ${String(e)}`;
  }

  return {
    config,
    themeEditorUrl,
    themeEditorAppEmbedsUrl,
    activeThemeName,
    appEmbedEnabled,
    embedDebug,
  };
};

