                action={{ content: "Edit Widget in Theme", url: `${themeEditorUrl}?template=product`, external: true }}
              >
                <Text as="p" variant="bodySm">
                  {activeThemeName ? `Active theme: ${activeThemeName}. ` : ""}
                  Settings saved here apply to shoppers instantly.
